/* Responsive, semantic home and asset library. Shared catalogue/state with the design prototype. */

window.renderMarketplace=(page,{state,matches,go,action})=>{

 const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

 const count=type=>RM_ASSETS.filter(a=>a.cat===type).length;

 const mark='<svg viewBox="0 0 32 36" aria-hidden="true"><path fill="#dce4ec" d="M2 7 16 0l14 8-14 8Z"/><path fill="#7995ad" d="m2 7 14 9v20L2 28Z"/><path fill="#477da4" d="m16 16 14-8v14l-7 4 7 10H19L9 22Z"/><path fill="#c4ccd3" d="m16 16 7 4 7-4v6l-7 4-7-4Z"/></svg>';

 const search=(label,hero=false)=>'<form class="m-search '+(hero?'m-search-hero':'')+'" role="search"><input class="m-search-field" aria-label="'+label+'" value="'+e(state.fields.search||'')+'" placeholder="'+(hero?'Search models, materials and scenes':'Search the library')+'" autocomplete="off"><button aria-label="'+(hero?'Search library':'Submit search')+'">'+(hero?'Search assets':'Search')+'</button></form>';

 const card=a=>'<article class="m-card"><div class="m-card-preview"><a href="asset.html?id='+a.id+'" aria-label="View '+e(a.title)+'"><img loading="lazy" decoding="async" width="560" height="420" src="../assets/thumbnails/'+a.file+'.webp" alt="'+e(a.title)+'"></a><button class="m-save" data-save="'+a.id+'" aria-label="'+(state.saved.has(a.id)?'Remove saved ':'Save ')+e(a.title)+'" aria-pressed="'+state.saved.has(a.id)+'">'+(state.saved.has(a.id)?'-':'+')+'</button></div><div class="m-card-info"><a class="m-card-title" href="asset.html?id='+a.id+'">'+e(a.title)+'</a><a class="m-card-creator" href="#'+a.creatorRoute+'">'+e(a.creator)+' <span>↗</span></a><div class="m-card-meta"><span>BLEND · GLB</span><strong>'+(a.price===null?'Portfolio scene':'₦'+a.price.toLocaleString('en-NG'))+'</strong></div><div class="m-card-place">'+e(a.placeLabel||a.region||'Object study')+'</div></div></article>';

 const radio=(group,label,value,selected)=>'<label class="m-option"><input type="radio" name="'+group+'" value="'+e(value)+'" '+(selected?'checked':'')+'><span>'+e(label)+'</span></label>';

 const nav='<header class="m-header"><a href="#home" class="m-brand">'+mark+'<span>RenderMarket</span></a><nav aria-label="Marketplace navigation"><a href="#home" '+(page==='home'?'aria-current="page"':'')+'>Home</a><a href="#explore" '+(page==='explore'?'aria-current="page"':'')+'>Marketplace</a><a href="#creator">Creators</a></nav>'+(page==='home'?'':search('Search marketplace'))+'<a href="#saved" class="m-saved-link">Saved <span>'+state.saved.size+'</span></a><a href="#register" class="m-studio-link">Creator studio ↗</a></header>';

 const categories=[['Models & props','3D models',count('3D models')],['Materials & textiles','Materials',count('Materials')],['Environments','Environments',count('Environments')],['All assets','All assets',RM_ASSETS.length]];

 let content='';


 if(page==='home'){
  content=`<section class="b-hero" aria-labelledby="brand-heading"><div class="b-intro"><p class="m-eyebrow">RENDERMARKET / AFRICAN CREATIVE WORLDS</p><h1 id="brand-heading">African worlds.<br>Ready to explore.</h1><p class="b-lead">Everyday places. Extraordinary possibilities.</p><p class="m-description">Discover the scenes, objects and materials that give a world its character. Created around African places and perspectives.</p><div class="m-hero-actions"><a class="m-primary" href="#explore">Enter the marketplace</a><a href="asset.html?id=sanctuary">Experience a scene in 3D</a></div><div class="b-home-search">${search('Search the RenderMarket catalogue',true)}<div class="m-suggestions"><span>Suggested</span><button data-query="danfo">Danfo</button><button data-query="lagos everyday">Lagos scenes</button><button data-query="textile">Textiles</button></div></div><p class="b-caption">An independent UI/UX portfolio project by Adefioye Favour.</p></div><figure class="b-hero-work"><a href="asset.html?id=sanctuary" aria-label="View Sanctuary Temple"><img src="../assets/previews/sanctuary-temple-960.webp" srcset="../assets/previews/sanctuary-temple-480.webp 480w, ../assets/previews/sanctuary-temple-960.webp 960w, ../assets/previews/sanctuary-temple-1440.webp 1440w" sizes="(max-width:800px) 100vw, 55vw" fetchpriority="high" decoding="async" width="960" height="540" alt="Sanctuary Temple, a forest scene with stone steps and lanterns"></a><figcaption><span>01 / FEATURED ENVIRONMENT</span><strong>Sanctuary Temple</strong><a href="#creator:owner">Adefioye Favour / fioye_3d</a></figcaption></figure></section>


<section class="b-worlds" aria-labelledby="worlds-title"><div class="m-section-heading"><div><p class="m-eyebrow">SCENES FROM EVERYDAY LIFE</p><h2 id="worlds-title">Somewhere familiar.<br>Something worth creating.</h2></div><a href="#explore?search=lagos%20everyday">Discover Everyday Lagos</a></div><div class="b-world-strip">${[['market','lagos-produce-market','02','The morning market'],['suya','lagos-suya-spot','03','An evening suya spot'],['football','lagos-football-field','04','A pitch for the neighbourhood'],['akara-vendor','lagos-akara-vendor','05','Breakfast on the corner']].map(([id,file,n,title])=>'<a href="asset.html?id='+id+'"><img src="../assets/previews/'+file+'-480.webp" width="480" height="360" loading="lazy" decoding="async" alt="'+title+' 3D scene"><div><span>'+n+' / LAGOS</span><strong>'+title+'</strong></div></a>').join('')}</div></section>
  <section class="b-discovery" aria-labelledby="browse-title"><div class="m-section-heading"><div><p class="m-eyebrow">THE LIBRARY / FIND YOUR MEDIUM</p><h2 id="browse-title">Find your starting point.</h2></div><a href="#explore">Browse all ${RM_ASSETS.length} assets</a></div><div class="m-categories">${categories.map(([title,type,n],i)=>'<button data-category="'+type+'"><img src="../assets/thumbnails/'+['danfo-minibus','kente-strip-study','lagos-canteen','sanctuary-temple'][i]+'.webp" alt="" loading="lazy" decoding="async" width="64" height="64"><span>'+title+'<small>'+n+' listings</small></span></button>').join('')}</div></section>
  <section class="b-selection" aria-labelledby="selection-title"><div class="m-section-heading"><div><p class="m-eyebrow">FROM THE CATALOGUE</p><h2 id="selection-title">Objects with a sense of place.</h2><p class="m-muted">A selection of models and materials from the portfolio collection.</p></div><a href="#explore">View all assets</a></div><div class="m-grid">${['orbit','loop','kente','baobab'].map(id=>RM_ASSETS.find(a=>a.id===id)).filter(Boolean).map(card).join('')}</div></section>
  <section class="b-collection" aria-labelledby="collection-title"><div class="m-section-heading"><div><p class="m-eyebrow">A CLOSER LOOK</p><h2 id="collection-title">Everyday Lagos, in 3D.</h2><p class="m-muted">Contemporary scenes built around familiar places.</p></div><a href="#explore?search=lagos%20everyday">Explore the collection</a></div><div class="b-diptych"><figure><a href="asset.html?id=canteen"><img loading="lazy" decoding="async" width="960" height="720" src="../assets/previews/lagos-canteen-960.webp" srcset="../assets/previews/lagos-canteen-480.webp 480w, ../assets/previews/lagos-canteen-960.webp 960w" sizes="(max-width:700px) 100vw, 50vw" alt="Contemporary Lagos canteen scene"></a><figcaption><strong>The neighbourhood canteen</strong><span>Environment study / Nigeria</span></figcaption></figure><figure><a href="asset.html?id=barbershop"><img loading="lazy" decoding="async" width="960" height="720" src="../assets/previews/lagos-barbershop-960.webp" srcset="../assets/previews/lagos-barbershop-480.webp 480w, ../assets/previews/lagos-barbershop-960.webp 960w" sizes="(max-width:700px) 100vw, 50vw" alt="Lagos barbershop scene with static characters"></a><figcaption><strong>A place for a fresh cut</strong><span>Environment study / Nigeria</span></figcaption></figure></div></section>
  <section class="b-inspect" aria-labelledby="inspect-title"><p class="m-eyebrow">LOOK BEYOND THE RENDER</p><div><h2 id="inspect-title">Open the scene.<br>See how it is made.</h2><p>Orbit the actual geometry, switch to wireframe and review the file details. Sanctuary Temple includes an interactive preview and an original Blender source file. Checkout is being prepared.</p><a class="b-text-link" href="asset.html?id=sanctuary">Open the interactive 3D viewer</a></div></section>
  <section class="b-story" aria-labelledby="story-title"><div><p class="m-eyebrow">THE IDEA</p><h2 id="story-title">African creativity.<br>Global possibility.</h2></div><div><p>Our everyday surroundings belong in digital worlds too. A Lagos canteen. A market before opening. The objects, textures and spaces that make a place feel familiar.</p><p>RenderMarket brings that perspective into a digital asset library, alongside original imagined environments. The work comes first, with clear previews, file details and creator attribution.</p></div></section>
<section class="b-formats" aria-labelledby="formats-title"><div><p class="m-eyebrow">FILES FOR YOUR WORKFLOW</p><h2 id="formats-title">Know what you are opening.</h2><p>Every listing includes these four formats. Check the asset page for file sizes, contents and usage terms.</p></div><dl><div><dt>Blender <span>.blend</span></dt><dd>Editable scene and source materials.</dd></div><div><dt>glTF Binary <span>.glb</span></dt><dd>Portable model used in the browser viewer.</dd></div><div><dt>Wavefront <span>.obj</span></dt><dd>Geometry with supporting material files in a ZIP.</dd></div><div><dt>FBX <span>.fbx</span></dt><dd>Export for compatible 3D applications.</dd></div></dl><a class="b-text-link" href="asset.html?id=sanctuary#files">Review the featured scene files</a></section>
  <section class="b-closing" aria-labelledby="closing-title"><p class="m-eyebrow">START EXPLORING</p><h2 id="closing-title">Find a world to build on.</h2><p>Browse ${RM_ASSETS.length} portfolio listings across models, materials and environments.</p><div class="m-hero-actions"><a class="m-primary" href="#explore">Enter the marketplace</a><a href="#register">View the creator workflow</a></div><small>Catalogue prices and publishing flows are demonstrations. No transactions take place.</small></section>`;
 }else{

  const list=matches();

  content='<section class="m-library-heading"><p class="m-eyebrow">ASSET LIBRARY</p><h1>Explore assets</h1><p class="m-muted">Models, materials and environments with downloadable source files.</p>'+search('Search assets',true)+'<div class="m-suggestions"><span>Browse</span><button data-query="lagos everyday">Everyday Lagos · 10 assets</button><button data-query="characters">With characters</button></div></section><div class="m-library"><aside class="m-filters"><div class="m-filter-heading"><strong>Filters</strong><button data-reset>Reset</button></div><fieldset><legend>Asset type</legend>'+['All assets','3D models','Materials','Environments'].map(c=>radio('category',c,c,state.category===c)).join('')+'</fieldset><fieldset><legend>Price</legend>'+[['Any price',0],['Under ₦10,000',1],['₦10,000 and above',2]].map(([label,v])=>radio('price',label,v,state.price===v)).join('')+'</fieldset><fieldset><legend>Place reference</legend>'+['All places','Nigeria','Ghana','Mali','Tanzania','Kenya','Guinea','Senegal'].map(c=>radio('region',c,c,state.region===c)).join('')+'</fieldset><div class="m-compatibility"><span>Source software</span><strong>Blender 4.2</strong><small>Portable GLB, OBJ and FBX exports are listed on each asset page.</small></div></aside><section class="m-results" aria-label="Asset results"><div class="m-results-header"><strong role="status">'+list.length+' '+(list.length===1?'asset':'assets')+'</strong><label>Sort by <select aria-label="Sort assets"><option value="featured" '+(state.sort==='featured'?'selected':'')+'>Featured</option><option value="price-asc" '+(state.sort==='price-asc'?'selected':'')+'>Price: low to high</option><option value="price-desc" '+(state.sort==='price-desc'?'selected':'')+'>Price: high to low</option></select></label></div>'+(list.length?'<div class="m-grid">'+list.map(card).join('')+'</div>':'<div class="m-empty"><h2>No matching assets</h2><p>Try a different search or reset the filters.</p><button data-reset>Reset filters</button></div>')+'</section></div>';

 }

 document.body.dataset.page=page;const root=document.querySelector('#artboard');root.classList.add('native-artboard');root.classList.toggle('mobile',state.forcedMobile);root.innerHTML='<div class="m-shell">'+nav+'<div class="m-main">'+content+'<footer class="m-footer"><span>RenderMarket · Independent portfolio project</span><span>Portfolio catalogue. Purchasing is not available yet.</span></footer></div><nav class="m-mobile-nav" aria-label="Mobile navigation"><a href="#home" '+(page==='home'?'aria-current="page"':'')+'>Home</a><a href="#explore" '+(page==='explore'?'aria-current="page"':'')+'>Explore</a><a href="#saved">Saved '+state.saved.size+'</a><a href="#register">Creator studio</a></nav></div>';

 root.querySelectorAll('.m-search').forEach(form=>form.onsubmit=event=>{event.preventDefault();state.fields.search=form.querySelector('.m-search-field').value;go('explore')});

 root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>action('save:'+b.dataset.save));

 root.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>action('query:'+b.dataset.query));

 root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.fields.search='';state.region='All places';state.price=0;action('category:'+b.dataset.category)});

 root.querySelectorAll('input[type=radio]').forEach(input=>input.onchange=()=>{state[input.name]=input.name==='price'?Number(input.value):input.value;window.renderMarketplace(page,{state,matches,go,action})});

 const sort=root.querySelector('select');if(sort)sort.onchange=()=>{state.sort=sort.value;window.renderMarketplace(page,{state,matches,go,action})};

 root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{state.fields.search='';state.region='All places';state.category='All assets';state.price=0;state.sort='featured';history.replaceState(null,'','#explore');window.renderMarketplace(page,{state,matches,go,action})});

 document.querySelector('#screen-title').textContent=page==='home'?'RenderMarket marketplace':'Explore assets';document.title=(page==='home'?'RenderMarket':'Explore assets')+' | 3D asset portfolio';

};
